# Verify updated alarms state
access_token = apis.phone.login(username='4436271690', password='1YEfc]J')['access_token']
api = apis.phone
alarms = []
page_index = 0
page_limit = 20
while True:
    page = api.show_alarms(access_token=access_token, page_index=page_index, page_limit=page_limit)
    if not page:
        break
    alarms.extend(page)
    page_index += 1

print('alarms after updates:', len(alarms))
for a in sorted(alarms, key=lambda x: x['alarm_id']):
    print(a['alarm_id'], a['label'], a['time'], 'enabled=', a['enabled'])

# Expected: alarm_id 122 time 22:30 enabled True; all others enabled False
expected = {a['alarm_id']: {'time': a['time'], 'enabled': a['enabled']} for a in alarms}
print('go-to-sleep expected check:', expected[122])
violations = []
for a in alarms:
    if a['alarm_id'] == 122:
        if a['time'] != '22:30' or a['enabled'] != True:
            violations.append(('go_to_sleep', a['alarm_id'], a['time'], a['enabled']))
    else:
        if a['enabled'] != False:
            violations.append(('other_enabled', a['alarm_id'], a['time'], a['enabled']))
print('violations:', violations)

